using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class SetupOffroadDust{
 public static string Main(){if(EditorApplication.isPlaying)throw new System.Exception("Stop Play");const string dir="Assets/Environments/OffroadCourse";var tex=new Texture2D(128,128,TextureFormat.RGBA32,true){name="Soft Dust",wrapMode=TextureWrapMode.Clamp};var pixels=new Color[128*128];for(int y=0;y<128;y++)for(int x=0;x<128;x++){float r=new Vector2((x-63.5f)/63.5f,(y-63.5f)/63.5f).magnitude;float a=Mathf.Pow(Mathf.Clamp01(1-r*r),2f);a*=Mathf.Lerp(.65f,1f,Mathf.PerlinNoise(x/12f,y/12f));pixels[y*128+x]=new Color(1,1,1,a);}tex.SetPixels(pixels);tex.Apply();AssetDatabase.CreateAsset(tex,dir+"/Soft Dust.asset");var shader=Shader.Find("Universal Render Pipeline/Particles/Unlit");if(shader==null)throw new System.Exception("URP particle shader missing");var mat=new Material(shader){name="Offroad Dust"};mat.SetTexture("_BaseMap",tex);mat.SetColor("_BaseColor",Color.white);mat.SetFloat("_Surface",1);mat.SetFloat("_Blend",0);mat.SetFloat("_SrcBlend",(float)UnityEngine.Rendering.BlendMode.SrcAlpha);mat.SetFloat("_DstBlend",(float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);mat.SetFloat("_ZWrite",0);mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");mat.SetOverrideTag("RenderType","Transparent");mat.renderQueue=3000;AssetDatabase.CreateAsset(mat,dir+"/Offroad Dust.mat");int count=0;foreach(var guid in AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Prefabs/TestDrive"})){var path=AssetDatabase.GUIDToAssetPath(guid);var root=PrefabUtility.LoadPrefabContents(path);try{var dust=root.GetComponent<TestDriveDust>();if(dust==null)dust=root.AddComponent<TestDriveDust>();var so=new SerializedObject(dust);so.FindProperty("dustMaterial").objectReferenceValue=mat;so.FindProperty("maximumParticlesPerWheel").floatValue=32;so.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.SaveAsPrefabAsset(root,path);count++;}finally{PrefabUtility.UnloadPrefabContents(root);}}
 foreach(var surface in Object.FindObjectsByType<TestDriveSurface>()){bool gravel=surface.name.Contains("Gravel")||surface.name.Contains("Truck");var so=new SerializedObject(surface);so.FindProperty("dustColor").colorValue=gravel?new Color(.72f,.67f,.56f,.42f):new Color(.73f,.59f,.41f,.42f);so.ApplyModifiedPropertiesWithoutUndo();}EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();return "Configured soft world-space dust on "+count+" driving prefabs, with dirt and gravel colors.";}}
